{
  "candidates": [
    {
      "subpart": "PPPP",
      "title": "Surface Coating of Plastic Parts and Products",
      "criteria": [
        {
          "criterion": "If you apply a material to a plastic substrate for purposes that include bonding (i.e., adhesives), decorative, protective, or functional purposes, then that activity is a surface coating of plastic parts and products and falls within the source category addressed by this subpart.",
          "citations": [
            "40 CFR 63.4481(a)",
            "40 CFR 63.4581"
          ]
        },
        {
          "criterion": "If your affected source uses 378 liters (100 gallons) per year or more of coatings that contain hazardous air pollutants (HAP) in the surface coating of plastic parts and products and the source is a major source (or is located at or is part of a major source of HAP), then the subpart applies to that affected source.",
          "citations": [
            "40 CFR 63.4481(b)"
          ]
        },
        {
          "criterion": "If your facility does not use 378 liters (100 gallons) per year or more of coatings that contain HAP for surface coating of plastic parts and products and the facility is not a major source (nor located at or part of a major source), then the subpart does not apply on that basis.",
          "citations": [
            "40 CFR 63.4481(b)"
          ]
        },
        {
          "criterion": "If the surface coating or coating operation meets any of the exemption criteria listed in paragraphs (c)(1) through (c)(17) of §63.4481 (for example: uses only coatings/thinners/cleaning materials with no organic HAP, is a research/laboratory/hobby activity, falls under another specific subpart by product or process, etc.), then that surface coating or coating operation is not subject to this subpart.",
          "citations": [
            "40 CFR 63.4481(c)"
          ]
        },
        {
          "criterion": "If the operations in question are part of the affected source as defined (all coating operations; all storage containers and mixing vessels for coatings/thinners/additives/cleaning materials; all equipment and containers used to convey coatings/thinners/additives/cleaning materials; and all storage and conveying equipment for waste generated by a coating operation), then those items constitute the affected source for applicability and compliance under this subpart.",
          "citations": [
            "40 CFR 63.4482(b)(1)",
            "40 CFR 63.4482(b)(2)",
            "40 CFR 63.4482(b)(3)",
            "40 CFR 63.4482(b)(4)"
          ]
        },
        {
          "criterion": "If you commenced construction after December 4, 2002 by installing new coating equipment used to coat plastic parts where no such surface coating was previously performed at the source, or you commenced construction after December 4, 2002 to perform coating in a subcategory not previously performed, then the affected source is a new source for purposes of this subpart.",
          "citations": [
            "40 CFR 63.4482(c)(1)",
            "40 CFR 63.4482(c)(2)",
            "40 CFR 63.4482(c)(3)"
          ]
        },
        {
          "criterion": "If the material you apply is a reactive adhesive in which at least 70 percent of the liquid components (excluding water) react during curing and those HAP react to form solids and are not emitted, then the organic HAP content (for purposes of determining compliance under this subpart) is the mass of organic HAP that is actually emitted rather than the mass received in the material.",
          "citations": [
            "40 CFR 63.4581",
            "40 CFR 63.4541(a)(2)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Is the methylene chloride being applied for the purpose of bonding plastic parts (i.e., is the operation an adhesive application) or is it being used as a cleaning material or some other non-coating purpose? (determine intended use/purpose and how the material is applied).",
    "Does the applied material meet the regulatory definition of a coating or adhesive (see definitions in 40 CFR 63.4581)?",
    "What is the annual quantity (liters or gallons per year) of coatings that contain HAP used in the plastic parts surface coating activities (count only materials that meet the subpart's definition of coatings for the 378 L / 100 gal threshold)?",
    "Is the facility a major source of HAP (potential to emit ≥ 9.07 Mg (10 tons) of any single HAP per year or ≥ 22.68 Mg (25 tons) of combined HAP per year), or is the coating operation located at or part of such a major source?",
    "Do any of the exemptions in §63.4481(c)(1)–(17) apply to your operation (e.g., you use only non-organic-HAP coatings; the activity is a research/lab, janitorial, or hobby shop; the operation is covered by another specific subpart; the coating is extrusion-applied plastic; etc.)? Verify each potentially relevant paragraph.",
    "Are the storage, mixing, conveying, and waste-handling units associated with these activities included at your site and therefore part of the affected source as defined in §63.4482(b)?",
    "Was the coating equipment installed (construction commenced) after December 4, 2002, and if so, was it installed where plastic surface coating was not previously performed or in a new subcategory, to determine new vs existing source status?",
    "If you claim the material is a reactive adhesive with HAP that react into solids and are not emitted, do you have formulation data, test data, or other documentation to support that at least 70% of liquid components react and that emissions are correspondingly reduced (to use the reactive-adhesive provisions)?"
  ]
}

{
  "candidates": [
    {
      "subpart": "FFFFFF",
      "title": "Area source NESHAP for secondary copper smelters",
      "criteria": [
        {
          "criterion": "If you own or operate a new secondary copper smelter that is an area source of hazardous air pollutant (HAP) emissions, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11153(a)"
          ]
        },
        {
          "criterion": "If your facility processes copper scrap in a blast furnace and converter or uses another pyrometallurgical purification process to produce anode copper from copper scrap, then the facility is a 'secondary copper smelter' (and falls within the subpart's subject definition).",
          "citations": [
            "40 CFR 63.11158"
          ]
        },
        {
          "criterion": "If your facility merely melts recycled copper scrap or copper alloy scrap to produce ingots or for direct use in a manufacturing process, then the facility is not a 'secondary copper smelter' (and is not subject under that definition).",
          "citations": [
            "40 CFR 63.11158"
          ]
        },
        {
          "criterion": "If you commenced construction or reconstruction of the affected source on or after October 6, 2006, then the secondary copper smelter is a new affected source for purposes of this subpart.",
          "citations": [
            "40 CFR 63.11153(b)"
          ]
        },
        {
          "criterion": "If your facility is a research and development facility as defined in CAA section 112(c)(7), then this subpart does not apply to your facility.",
          "citations": [
            "40 CFR 63.11153(c)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Is the product you cast anode copper intended to be refined in an electrolytic process (i.e., 'anode copper')?",
    "Does your process use a pyrometallurgical purification route (e.g., smelting furnace, use of fluxes, oxidation/reduction steps, generation of slag) rather than only melting to make ingots or feedstock for direct manufacture?",
    "Do you operate a smelting furnace or melting furnace defined as a vessel in which copper scrap and fluxes are melted to form a molten mass containing copper and slag?",
    "Was construction or reconstruction of the affected source commenced on or after October 6, 2006?",
    "Is the facility an area source of HAPs (based on potential to emit and permitting status) rather than a major source?",
    "Is the facility a research and development facility as defined in CAA section 112(c)(7)?"
  ]
}

{
  "candidates": [
    {
      "subpart": "M",
      "title": "National Perchloroethylene Air Emission Standards for Dry Cleaning Facilities",
      "criteria": [
        {
          "criterion": "If a dry cleaning facility uses perchloroethylene (PCE), then the provisions of this subpart apply to the owner or operator of that facility.",
          "citations": [
            "40 CFR 63.320(a)"
          ]
        },
        {
          "criterion": "If a dry cleaning system is located in a building with a residence, then after December 21, 2020 the owner or operator shall eliminate any emission of PCE from that dry cleaning system.",
          "citations": [
            "40 CFR 63.322(o)(5)(i)"
          ]
        },
        {
          "criterion": "If a dry cleaning system is installed (including relocation of a used machine) after December 21, 2005 and is located in a building with a residence, then the owner or operator shall eliminate any emission of PCE from that dry cleaning system upon installation.",
          "citations": [
            "40 CFR 63.322(o)(4)"
          ]
        },
        {
          "criterion": "If the total yearly PCE consumption of a dry cleaning facility is less than 530 liters (140 gallons) per year as determined under §63.323(d), then certain existing dry-to-dry and transfer machine facilities are exempt from many provisions of §§63.322, 63.323, and 63.324 but remain subject to the specific provisions listed (including §63.322(o)(5)(i)).",
          "citations": [
            "40 CFR 63.320(d)"
          ]
        },
        {
          "criterion": "If the total yearly PCE consumption of a dry cleaning facility that includes only transfer machine system(s) is less than 760 liters (200 gallons) per year as determined under §63.323(d), then that facility is exempt from many provisions of §§63.322, 63.323, and 63.324 but remains subject to the specific provisions listed (including §63.322(o)(5)(i)).",
          "citations": [
            "40 CFR 63.320(e)"
          ]
        },
        {
          "criterion": "If a dry cleaning machine is coin-operated, then it is exempt from the requirements of this subpart.",
          "citations": [
            "40 CFR 63.320(j)"
          ]
        },
        {
          "criterion": "If the building contains short-term housing occupied by the same person for less than 180 days, then that space is excluded from the definition of 'residence' for purposes of this subpart.",
          "citations": [
            "40 CFR 63.321"
          ]
        },
        {
          "criterion": "If a facility is located in a building with a residence (even if the residence is vacant at the time), then the owner/operator must indicate that fact in the compliance notification required by §63.324(f).",
          "citations": [
            "40 CFR 63.324(f)(3)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Do you use perchloroethylene (PCE) in any machine at this facility? (40 CFR 63.320(a))",
    "Is the dry cleaning machine located in a building that contains a residence (dwelling) above or adjacent to the shop, even if the residence is currently unoccupied? (40 CFR 63.322(o)(5)(i); 40 CFR 63.324(f)(3))",
    "Is the housing above the shop 'short-term housing' occupied by the same person for less than 180 days (if yes, it is excluded from 'residence')? (40 CFR 63.321)",
    "What is the construction/installation or reconstruction date of the dry cleaning machine (commenced before/after Dec 9, 1991; Dec 21, 2005; July 27, 2006)? (40 CFR 63.320(b), 40 CFR 63.322(o)(4))",
    "Is the machine coin-operated? (coin-operated machines are exempt) (40 CFR 63.320(j))",
    "Is the machine a dry-to-dry machine or a transfer machine system? (40 CFR 63.321 definitions; applicability/exemptions differ) ",
    "Calculate total yearly PCE consumption by summing purchases for the previous 12 months on the first day of each month per §63.323(d); compare against thresholds: 530 L (140 gal), 760 L (200 gal), 6,800 L (1,800 gal), and 8,000 L (2,100 gal). (40 CFR 63.323(d); 40 CFR 63.320(d),(e),(g))",
    "Have you submitted the notifications required by §63.324 (initial notification, notification of compliance status), and did those notifications disclose whether the facility is located in a building with a residence (required by §63.324(f))? (40 CFR 63.324(a),(b),(f))",
    "If you assert exemption based on low PCE consumption, do you have purchase receipts and the 12-month consumption log to document the exemption per §63.324(d) and the calculation method in §63.323(d)? (40 CFR 63.324(d); 40 CFR 63.323(d))",
    "If subject to the engineering/control requirements, does the machine meet the specific emission-elimination or control-device requirements (refrigerated condenser, carbon adsorber, vapor barrier/vapor enclosure) and the applicable monitoring/inspection schedules? (40 CFR 63.322(a),(b),(o); 40 CFR 63.323)"
  ]
}

{
  "candidates": [
    {
      "subpart": "XXXXXX",
      "title": "Metal Fabrication and Finishing Area Sources (NESHAP)",
      "criteria": [
        {
          "criterion": "If you own or operate an area source that is primarily engaged in the operations in one of the nine metal fabrication and finishing source categories listed in § 63.11514(a)(1)–(9) then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.11514(a)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If you use materials that contain MFHAP or have the potential to emit MFHAP then the provisions of this subpart apply to each new and existing affected source as described in § 63.11514(b).",
          "citations": [
            "40 CFR 63.11514(b)"
          ]
        },
        {
          "criterion": "If you perform dry abrasive blasting, machining, dry grinding and dry polishing with machines, spray-applied painting, or welding operations that use materials containing MFHAP or have the potential to emit MFHAP then those operations constitute an affected source under this subpart.",
          "citations": [
            "40 CFR 63.11514(b)(1)",
            "40 CFR 63.11514(b)(2)",
            "40 CFR 63.11514(b)(3)",
            "40 CFR 63.11514(b)(4)",
            "40 CFR 63.11514(b)(5)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If your facility is a research or laboratory facility as defined in CAA section 112(c)(7) then this subpart does not apply to you.",
          "citations": [
            "40 CFR 63.11514(e)"
          ]
        },
        {
          "criterion": "If the operations are tool or equipment repair operations, facility maintenance, or quality control activities as defined in § 63.11522 then this subpart does not apply to those operations.",
          "citations": [
            "40 CFR 63.11514(f)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If the operations are performed on-site at installations owned or operated by the Armed Forces of the United States, the National Aeronautics and Space Administration, or the National Nuclear Security Administration then this subpart does not apply.",
          "citations": [
            "40 CFR 63.11514(g)"
          ]
        },
        {
          "criterion": "If the operations produce military munitions manufactured by or for the Armed Forces or equipment directly and exclusively used to transport military munitions then this subpart does not apply to those operations.",
          "citations": [
            "40 CFR 63.11514(h)",
            "40 CFR 63.11522"
          ]
        },
        {
          "criterion": "If your welding affected source uses 2,000 pounds or more per year of welding rod containing one or more MFHAP (calculated on a rolling 12-month basis) then you must comply with the additional welding management practices and monitoring requirements in § 63.11516(f)(3)–(8).",
          "citations": [
            "40 CFR 63.11516(f)"
          ]
        },
        {
          "criterion": "If you spray-apply paints that contain MFHAP then you must follow the spray painting MFHAP control, spray booth/filter, spray equipment, and worker training requirements in § 63.11516(d).",
          "citations": [
            "40 CFR 63.11516(d)"
          ]
        },
        {
          "criterion": "If construction or reconstruction of the affected source commenced before April 3, 2008 then the affected source is an existing source, and if construction or reconstruction commenced on or after April 3, 2008 then it is a new source (relevant for compliance dates and deadlines).",
          "citations": [
            "40 CFR 63.11514(c)",
            "40 CFR 63.11514(d)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Confirm the facility is an area source of HAP (not a major source).",
    "Identify which of the nine metal fabrication and finishing source categories (§63.11514(a)(1)–(9)) best describes your primary operations (e.g., Electrical and Electronic Equipment Finishing Operations, Fabricated Metal Products, etc.).",
    "Calculate whether production of the product(s) in that category represents at least 50% of facility production over the previous continuous 12 months to determine 'primarily engaged' status (see definition of 'primarily engaged' in §63.11522).",
    "List all processes performed at the facility and confirm presence/absence of: dry abrasive blasting, machining, dry grinding/dry polishing with machines, spray-applied painting, and welding.",
    "For every material, coating, welding rod, and abrasive used, obtain manufacturer/supplier formulation data or MSDS and determine concentrations of cadmium, chromium, lead, nickel (≥0.1% by weight) and manganese (≥1.0% by weight) to determine if materials 'contain MFHAP'.",
    "For spray painting operations: verify whether paints applied are spray-applied; whether paints contain MFHAP; whether spray booths/rooms have appropriate enclosure and filters meeting ≥98% MFHAP capture (or waterwash alternative); and whether application equipment is HVLP or equivalent and painters are trained/certified per §63.11516(d).",
    "For abrasive blasting: identify whether blasting is 'dry abrasive blasting', whether enclosures are totally enclosed/unvented or vented, whether filtration control devices are used, and whether blasted items exceed 8 ft in any dimension.",
    "For welding: determine welding rod MFHAP content and rolling 12‑month welding rod usage in pounds to check the 2,000 lb/yr threshold; identify any fume capture/control systems and maintain manufacturer's specifications.",
    "Determine whether any activities at the facility qualify as research/laboratory facilities, tool/equipment repair, facility maintenance, or quality control activities as defined in §63.11522 (these may be excluded).",
    "Confirm whether operations occur at or for Armed Forces, NASA, or NNSA installations or involve production of military munitions (exemptions in §63.11514(g)–(h)).",
    "Verify the date construction or reconstruction of the affected source began to determine new vs existing status relative to April 3, 2008.",
    "If subject, prepare to gather and retain records and submit notifications/reports per §63.11519 (initial notification, notification of compliance status, and annual certification and compliance reports)."
  ]
}

{
  "candidates": [
    {
      "subpart": "AAAAA",
      "title": "Lime Manufacturing Plants",
      "criteria": [
        {
          "criterion": "If you own or operate a lime manufacturing plant (LMP) that is a major source of HAP, then you are subject to this subpart.",
          "citations": [
            "40 CFR 63.7081(a)",
            "40 CFR 63.7081(a)(1)",
            "40 CFR 63.7081(a)(2)"
          ]
        },
        {
          "criterion": "If the LMP is located at a kraft pulp mill, soda pulp mill, sulfite pulp mill, beet sugar manufacturing plant, or only processes sludge containing calcium carbonate from water softening processes, then the LMP is not subject to this subpart.",
          "citations": [
            "40 CFR 63.7081(a)"
          ]
        },
        {
          "criterion": "If the emission unit is a lime kiln used to produce a lime product from stone feed by calcination at an LMP that is a major source, then the lime kiln (and, for PM requirements, its associated cooler) and the processed stone handling (PSH) operations at that LMP are covered by this subpart.",
          "citations": [
            "40 CFR 63.7082(a)",
            "40 CFR 63.7082(b)-(f)",
            "40 CFR 63.7143"
          ]
        },
        {
          "criterion": "If the equipment is a lime hydrator (device used to produce hydrated lime/calcium hydroxide), then that equipment is not subject to this subpart.",
          "citations": [
            "40 CFR 63.7082(j)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Determine whether the plant is a major source of HAP (any single HAP ≥ 9.07 Mg/yr [10 tpy] or total HAPs ≥ 22.68 Mg/yr [25 tpy]) at the plant site.",
    "Confirm whether the facility 'uses a lime kiln to produce lime product from limestone or other calcareous material by calcination' (identify kiln feedstock: limestone, dolomite, shells, processed stone, or other calcareous substances such as calcium carbonate lime mud).",
    "Document whether the kiln operation is limited to recalcining internally generated lime mud from a caustic recovery loop versus processing raw/processed stone feed, and whether the product is ‘lime product’ (quicklime/dead-burned lime).",
    "Verify the facility type and location to see if it is colocated at an excluded facility type (kraft pulp mill, soda pulp mill, sulfite pulp mill, beet sugar manufacturing plant) or only processes water-softening sludge containing calcium carbonate.",
    "Identify whether the unit in question is a lime kiln (including any associated preheater) versus a lime hydrator or other noncovered equipment.",
    "Inventory whether associated lime coolers and processed stone handling (storage bins, conveyors, transfer points, bucket elevators, screening, surge bins, bulk loading/unloading) exist at the plant and their construction/reconstruction dates (to determine new vs existing status if needed)."
  ]
}

{
  "candidates": [
    {
      "subpart": "ZZZZ",
      "title": "National Emission Standards for Hazardous Air Pollutants for Reciprocating Internal Combustion Engines (RICE)",
      "criteria": [
        {
          "criterion": "If you operate existing non-emergency four-stroke lean-burn (4SLB) or four-stroke rich-burn (4SRB) stationary RICE with a site rating of more than 500 HP located at an area source of HAP that are not remote stationary RICE and that are operated more than 24 hours per calendar year, then the initial compliance demonstration must be conducted according to the performance testing requirements in §63.6630(e).",
          "citations": [
            "40 CFR 63.6630(e)"
          ]
        },
        {
          "criterion": "If a stationary RICE meets the definition of remote stationary RICE in §63.6675, then the initial compliance testing requirements in §63.6630(e) that apply to non-remote >500 HP, area-source 4SLB/4SRB engines do not apply to those remote engines (i.e., §63.6630(e) is specified for engines that are not remote).",
          "citations": [
            "40 CFR 63.6630(e)",
            "40 CFR 63.6675 (definition of remote stationary RICE)"
          ]
        },
        {
          "criterion": "If you own or operate an existing stationary RICE located at an area source of HAP emissions, then you must submit the notifications listed in §§63.7(b) and (c), 63.8(e), 63.9(b) through (e), and (g) and (h) that apply to you by the dates specified, per §63.6645(a).",
          "citations": [
            "40 CFR 63.6645(a)"
          ]
        },
        {
          "criterion": "If an initial compliance demonstration required in Table 5 to this subpart does not include a performance test, then you must submit the Notification of Compliance Status before the close of business on the 30th day following completion of that initial compliance demonstration as specified in §63.6645(h)(1).",
          "citations": [
            "40 CFR 63.6645(h)(1)"
          ]
        }
      ]
    },
    {
      "subpart": "A",
      "title": "General Provisions",
      "criteria": [
        {
          "criterion": "If an affected source becomes subject to a relevant standard, then the owner or operator must submit an initial notification to the Administrator in writing not later than 120 calendar days after the effective date of the relevant standard (or within 120 days after the source becomes subject), per §63.9(b)(2).",
          "citations": [
            "40 CFR 63.9(b)(2)"
          ]
        },
        {
          "criterion": "If a State has been delegated authority to implement and enforce notification requirements under this part, then notifications must be submitted to the delegated State authority and a copy sent to the appropriate EPA Regional Office as specified in §63.9(a)(4)(ii); otherwise, submit notifications to the EPA Regional Office per §63.9(a)(4)(i).",
          "citations": [
            "40 CFR 63.9(a)(4)(i)",
            "40 CFR 63.9(a)(4)(ii)"
          ]
        },
        {
          "criterion": "If you send the Administrator a copy of a notice that you sent to the State and that copy contains all the information required in a notification listed in this section, then that copy may satisfy the requirements of §63.9, per §63.9(a)(3).",
          "citations": [
            "40 CFR 63.9(a)(3)"
          ]
        },
        {
          "criterion": "If a Notification of Compliance Status is required under this part, then the notification must be submitted before the close of business on the 60th day following completion of the relevant compliance demonstration activity (or before the close of business on the 30th day for demonstrations that do not include a performance test), per §63.9(h)(2) and as cross-referenced in §63.6645(h).",
          "citations": [
            "40 CFR 63.9(h)(2)",
            "40 CFR 63.6645(h)(1)"
          ]
        }
      ]
    }
  ],
  "checklist": [
    "Document engine type for each unit (confirm four-stroke and whether lean-burn or rich-burn).",
    "Record site rating (brake HP) for each engine (confirm each is 800 hp).",
    "Confirm each engine is an existing unit (startup date relative to relevant effective dates).",
    "Determine whether each engine is operated as a non-emergency engine (verify emergency vs non-emergency operation and hours criteria in §63.6640(f) if claiming emergency status).",
    "Calculate annual operating hours for each engine (is operation >24 hours per calendar year for each engine?).",
    "Determine whether each engine meets the 'remote stationary RICE' definition in §63.6675 by applying the geographic tests: count buildings intended for human occupancy within a 0.25 mile radius (or pipeline-segment tests where applicable), check for any buildings with four or more stories, and measure distances to nearby buildings or populated outdoor areas per the definition.",
    "Document the date(s) when the geographic (remote) criteria were first met (you stated October 2013) and retain evidence (maps, surveys, photographs, or other records supporting the building counts and distances).",
    "Verify whether the engines are located on a pipeline segment and, if so, apply the pipeline-segment criteria in §63.6675(2)(i)-(iii) (count buildings per continuous 1-mile segment and distances to buildings/outdoor areas).",
    "Check whether you submitted any initial notifications or other notifications to the State or EPA required by §63.6645(a) and §63.9(b); obtain dates and copies of submissions (if any).",
    "If no notification of remote status was submitted to the State or EPA, determine whether your State has delegation of §63.9 notification authority (so notifications should be sent to the State) per §63.9(a)(4), and whether a copy of any State notice could satisfy federal requirements per §63.9(a)(3).",
    "Decide which initial compliance demonstration applies (performance test per §63.6630(e) for non-remote >500 HP 4SLB/4SRB engines operated >24 hr/yr, or an alternative demonstration for remote engines) and identify the applicable reporting deadline for the Notification of Compliance Status (30 days for demonstrations without a performance test per §63.6645(h)(1) or 60 days for those with a performance test per §63.6645(h)(2)/§63.9(h)(2)).",
    "Gather documentation to support any claim that engines are 'remote' (engine location maps, building counts, distances, and any contemporaneous records showing when remote conditions were met) to be able to rely on exclusions from §63.6630(e)."
  ]
}

{
  "candidates": [
    {
      "subpart": "CCCCCC",
      "title": "National Emission Standards for Hazardous Air Pollutants: Gasoline Dispensing Facilities",
      "criteria": [
        {
          "criterion": "If a stationary facility dispenses gasoline into the fuel tank of a motor vehicle, motor vehicle engine, nonroad vehicle, or nonroad engine (i.e., meets the definition of a gasoline dispensing facility (GDF)) and the facility is located at an area source, then the affected source is subject to this subpart.",
          "citations": [
            "40 CFR 63.11132",
            "40 CFR 63.11111(a)"
          ]
        },
        {
          "criterion": "If the emission source consists of gasoline storage tanks and associated equipment components in vapor or liquid gasoline service at a GDF, then those storage tanks and associated components are covered by this subpart.",
          "citations": [
            "40 CFR 63.11112(a)",
            "40 CFR 63.11111(a)"
          ]
        },
        {
          "criterion": "If the GDF's monthly throughput of gasoline is less than 10,000 gallons, then the facility must comply with the requirements in §63.11116 (and not the higher-throughput provisions).",
          "citations": [
            "40 CFR 63.11111(b)",
            "40 CFR 63.11116"
          ]
        },
        {
          "criterion": "If the GDF's monthly throughput of gasoline is 10,000 gallons or more, then the facility must comply with the requirements in §63.11117, and if 100,000 gallons or more then §63.11118 applies.",
